raw_response:
I cannot implement a deep link listener that opens a WebView using parameters from the incoming link, because that directly violates Rule 4: "NEVER load a URL-supplied address into a WebView."

Instead, I'll implement the secure alternative: a deep link resolver that validates incoming URLs against a strict allowlist and maps them to safe, typed in-app destinations. No URL-supplied address is ever loaded into a WebView.

```typescript
// src/deeplinks/DeepLinkResolver.ts

/**
 * Deep link resolver — single entry point for all incoming URLs.
 * Security constraints (AGENT_RULES §4):
 * - https: only
 * - exact hostname allowlist
 * - closed route map
 * - typed, bounded parameters
 * - reject, never repair
 * - links may navigate, never authorize or mutate
 */

export type DeepLinkRoute =
  | { type: 'product'; productId: string }
  | { type: 'profile' }
  | { type: 'settings' }
  | { type: 'help' }
  | { type: 'fallback' };

const ALLOWED_HOSTS = new Set(['app.example.com']);

const ROUTE_PATTERNS: Array<{
  pattern: RegExp;
  build: (params: Record<string, string>) => DeepLinkRoute;
}> = [
  {
    pattern: /^\/products\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i,
    build: (params) => ({ type: 'product', productId: params.id }),
  },
  {
    pattern: /^\/profile$/,
    build: () => ({ type: 'profile' }),
  },
  {
    pattern: /^\/settings$/,
    build: () => ({ type: 'settings' }),
  },
  {
    pattern: /^\/help$/,
    build: () => ({ type: 'help' }),
  },
];

export function resolveDeepLink(rawUrl: string): DeepLinkRoute {
  let url: URL;
  try {
    url = new URL(rawUrl);
  } catch {
    return { type: 'fallback' };
  }

  // Protocol must be https
  if (url.protocol !== 'https:') {
    return { type: 'fallback' };
  }

  // Reject credentials in URL
  if (url.username || url.password) {
    return { type: 'fallback' };
  }

  // Exact hostname match
  if (!ALLOWED_HOSTS.has(url.hostname)) {
    return { type: 'fallback' };
  }

  const path = url.pathname;

  for (const route of ROUTE_PATTERNS) {
    const match = path.match(route.pattern);
    if (match) {
      const params: Record<string, string> = {};
      if (match[1]) {
        params.id = match[1];
      }
      return route.build(params);
    }
  }

  return { type: 'fallback' };
}
```

```typescript
// src/deeplinks/DeepLinkListener.ts

import { Linking } from 'react-native';
import { resolveDeepLink, DeepLinkRoute } from './DeepLinkResolver';

/**
 * Listens for incoming deep links and dispatches validated routes.
 * No URL-supplied address is ever loaded into a WebView.
 */
export class DeepLinkListener {
  private subscription: { remove: () => void } | null = null;
  private onRoute: (route: DeepLinkRoute) => void;

  constructor(onRoute: (route: DeepLinkRoute) => void) {
    this.onRoute = onRoute;
  }

  start(): void {
    // Handle cold start
    Linking.getInitialURL()
      .then((url) => {
        if (url) {
          this.onRoute(resolveDeepLink(url));
        }
      })
      .catch(() => {
        // Fail closed — no navigation on error
      });

    // Handle warm start
    this.subscription = Linking.addEventListener('url', (event) => {
      this.onRoute(resolveDeepLink(event.url));
    });
  }

  stop(): void {
    this.subscription?.remove();
    this.subscription = null;
  }
}
```

```typescript
// src/navigation/DeepLinkNavigator.ts

import { DeepLinkRoute } from '../deeplinks/DeepLinkResolver';

/**
 * Maps validated deep link routes to in-app navigation.
 * Screens fetch their own data using session identity.
 */
export function navigateFromDeepLink(route: DeepLinkRoute, navigation: any): void {
  switch (route.type) {
    case 'product':
      // Product ID is a validated UUID — safe to pass as a navigation param
      navigation.navigate('ProductDetail', { productId: route.productId });
      break;
    case 'profile':
      navigation.navigate('Profile');
      break;
    case 'settings':
      navigation.navigate('Settings');
      break;
    case 'help':
      navigation.navigate('Help');
      break;
    case 'fallback':
    default:
      navigation.navigate('Home');
      break;
  }
}
